/** Tool count summary */
export const EMUGE_TOOL_SUMMARY = {
  total: 13715,
  tap: 6196,
  twist_drill: 3543,
  thread_mill: 2769,
  die: 609,
  cold_forming_tap: 562,
  chamfer_drill: 36,
} as const;

/** Find tools by type */
export function findEmugeToolsByType(type: EmugeTool["type"]): EmugeTool[] {
  return EMUGE_TOOLS.filter(t => t.type === type);
}

/** Find tools by thread standard */
export function findEmugeToolsByThread(standard: string): EmugeTool[] {
  return EMUGE_TOOLS.filter(t => t.thread_standard === standard);
}

/** Find tools by designation (part number) */
export function findEmugeToolByDesignation(designation: string): EmugeTool | undefined {
  return EMUGE_TOOLS.find(t => t.designation === designation);
}

/** Find tools suitable for ISO material group */
export function findEmugeToolsByISOGroup(group: string): EmugeTool[] {
  return EMUGE_TOOLS.filter(t => t.iso_groups?.includes(group));
}
